Method.Source:
/// <summary>
/// Inserted handler
/// </summary>
/// <param name="sender">Record</param>
/// <param name="e">Event</param>
[DataEventHandler(tableStr(UnitOfMeasureConversion), DataEventType::Inserted)]
public static void UnitOfMeasureConversion_onInserted(Common sender, DataEventArgs e)
{
    UnitOfMeasureConversion unitOfMeasureConversion = sender as UnitOfMeasureConversion;
    METPriceChangeEventProduct::metProcessTrackChange(InventTable::findByProduct(unitOfMeasureConversion.Product));
}
